{
  "id": "AGHR-029",
  "title": "مسار موحد لاستقبال التغييرات",
  "kind": "PROCEDURE",
  "force": "MUST",
  "severity": "high",
  "scope": {
    "paths": [
      "**"
    ]
  },
  "rule": "Applies when: When proposing rule or requirement changes.\nCapture original input, classify impact, reconcile and obtain the proper decision before applying effective changes.",
  "authority": {
    "source": "drafting/OWNER_DIRECTIVE.json",
    "level": "project",
    "owner": "Platform Governance Team",
    "approvedBy": "PROVISIONAL_OWNER_REVIEW",
    "status": "draft",
    "effectiveFrom": "2026-10-23"
  },
  "rationale": "تغيير قاعدة خارج مسار القرار قد ينشئ مرجعية موازية. PROVISIONAL_OWNER_REVIEW",
  "enforcement": {
    "textual": true,
    "failureAction": "review",
    "mergeEffect": "advisory"
  },
  "verification": {
    "evalFixtures": [
      "drafting/eval-fixtures.json#/AGHR-029"
    ]
  },
  "impact": {
    "band": "high",
    "evidence": "assumed"
  },
  "reviewCadence": "Owner review before activation and after material changes",
  "nextReview": "2027-01-21",
  "exceptions": {
    "allowed": false
  },
  "references": [
    "drafting/OWNER_DIRECTIVE.json"
  ]
}
